U_normal_solution:
import sys
input = sys.stdin.read
x, y, z = map(int, input().split())

if x + z < y:
    print("-")
elif y + z < x:
    print("+")
elif x > y and x - y > z:
    print("+")
elif y > x and y - x > z:
    print("-")
elif x == y and z == 0:
    print("0")
else:
    print("?")

